from collections import Counter
def f(g):
    H=len(g); W=len(g[0])
    cnt=Counter(x for row in g for x in row)
    order=[c for c,_ in sorted(cnt.items(), key=lambda kv:-kv[1])]
    sc,bg=order[-1],order[0]
    mask=[(r,c) for r in range(H) for c in range(W) if g[r][c]==sc]
    offs=tuple(sorted((r-min(a for a,_ in mask),c-min(b for _,b in mask)) for r,c in mask))
    out=[[int(x) for x in row] for row in g]
    for r in range(H):
        for c in range(W):
            if all(0<=r+a<H and 0<=c+b<W and g[r+a][c+b]==bg for a,b in offs):
                for a,b in offs:
                    out[r+a][c+b]=sc
    return out
